namespace ghidra.app.plugin.core.function;

using ghidra.app.services;
using ghidra.app.util.importer;
using ghidra.framework.options;
using ghidra.program.model.address;
using ghidra.program.model.listing;
using ghidra.util;
using ghidra.util.task;

/**
 * This analyzer creates only functions that are thunks early in the analysis pipeline.
 */

public class CreateThunkAnalyzer : FunctionAnalyzer {
	private static readonly string FIND_THUNKS_STARTS_MSG = "Create Thunks : ";

	private static readonly string OPTION_NAME_CREATE_THUNKS_EARLY = "Create Thunks Early";
	private static readonly string OPTION_DESCRIPTION_CREATE_THUNKS_EARLY =
		"If checked, create thunk functions early in analysis flow.";
	private static readonly bool OPTION_DEFAULT_CREATE_THUNKS_EARLY_ENABLED = true;

	public CreateThunkAnalyzer() : base()
    {
		setPriority(AnalysisPriority.BLOCK_ANALYSIS.after().after());
		setDefaultEnablement(true);
		createOnlyThunks = OPTION_DEFAULT_CREATE_THUNKS_EARLY_ENABLED;
		analysisMessage = FIND_THUNKS_STARTS_MSG;
	}

	/* @Override */
	public bool added(Program program, AddressSetView set, TaskMonitor monitor, MessageLog log) {
		if (!createOnlyThunks) {
			return true;
		}
		return base.added(program, set, monitor, log);
	}

	/* @Override */
	public void registerOptions(Options options, Program prog) {
		HelpLocation helpLocation = new HelpLocation("AutoAnalysisPlugin",
			"Auto_Analysis_Option_Instruction" + getAnalysisType());

		options.registerOption(OPTION_NAME_CREATE_THUNKS_EARLY, createOnlyThunks, null,
			OPTION_DESCRIPTION_CREATE_THUNKS_EARLY);
	}

	/* @Override */
	public void optionsChanged(Options options, Program prog) {
		createOnlyThunks = options.getBoolean(OPTION_NAME_CREATE_THUNKS_EARLY, createOnlyThunks);
	}
}
